from typing import List

def factorize(n: int) -> List[int]:
    def generate_prime_factors(num):
        factors = []
        divisor = 2
        while divisor <= num:
            if num % divisor == 0:
                factors.append(divisor)
                num = num / divisor
            else:
                divisor += 1
        return factors

    prime_factors = generate_prime_factors(n)
    prime_factors.sort()

    result = []
    for factor in prime_factors:
        count = prime_factors.count(factor)
        result.extend([factor] * count)

    product = 1
    for factor in result:
        product *= factor

    if product == n:
        return result
    else:
        raise ValueError("Input number is not equivalent to the product of all factors")

